  '{situation} {adjTail}로 분위기 업,\n{adjTail2}로 감성 한 스푼',
];
function makeAdjTailPhrase(adj: string) {
  const tails = adjTails[adj] || [];
  if (tails.length === 0) return adj;
  const tail = tails[Math.floor(Math.random() * tails.length)];
  if (adj.endsWith('한') || adj.endsWith('적인')) {
    return `${adj} ${tail}`;
  }
  return `${adj}${tail}`;
}
function generateConnectedPhrase(mood1: string, mood2: string) {
  // 두 무드(형용사)로 꼬리 조합, 상황 랜덤, 템플릿 랜덤
  const adjTail1 = makeAdjTailPhrase(mood1);
  const adjTail2 = makeAdjTailPhrase(mood2);
  const situation = situations[Math.floor(Math.random() * situations.length)];
  const template = templates[Math.floor(Math.random() * templates.length)];
  let phrase = template
    .replace(/\{adjTail\}/g, adjTail1)
    .replace(/\{adjTail2\}/g, adjTail2)
    .replace(/\{situation\}/g, situation);
  // 필터링: 반복, 어색한 꼬리, 단어만 오는 문장 등
  if (
    /([가-힣]+한)\1/.test(phrase) ||
    phrase.includes('하게하게') ||
    phrase.includes('적인하게') ||
    phrase.includes('소프트한 느낌') ||
    phrase.includes('실용적인하게')
  ) {
    return generateConnectedPhrase(mood1, mood2); // 재귀로 다시 생성
  }
  return phrase;
}

function rgbToSimpleColor([r, g, b]: number[]): string {
  // 간단한 색상 분류 (red, orange, yellow, green, blue, purple, pink, brown, black, gray, white)
  if (r > 200 && g < 100 && b < 100) return "red";
  if (r > 200 && g > 120 && b < 80) return "orange";
  if (r > 200 && g > 200 && b < 100) return "yellow";
  if (g > 150 && r < 120 && b < 120) return "green";
  if (b > 180 && r < 120 && g < 180) return "blue";
  if (r > 150 && b > 150 && g < 120) return "purple";
  if (r > 200 && g < 150 && b > 180) return "pink";
  if (r > 100 && g > 70 && b < 50) return "brown";
  if (r < 60 && g < 60 && b < 60) return "black";
  if (r > 200 && g > 200 && b > 200) return "white";
  if (r > 150 && g > 150 && b > 150) return "gray";
  return "gray";
}

const getRandomUnique = <T,>(arr: T[], n: number) => {
  const shuffled = arr.slice().sort(() => 0.5 - Math.random());
  return shuffled.slice(0, n);
};

const BannerCopyGenerator: React.FC = () => {
  const [image, setImage] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [copyType, setCopyType] = useState<"mypage" | "ribbon">("mypage");
  const [result, setResult] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const imgRef = useRef<HTMLImageElement>(null);
  const [colorMoods, setColorMoods] = useState<{color: string, mood: string}[]>([]);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImage(file);
      setPreviewUrl(URL.createObjectURL(file));
      setResult([]);
      setColorMoods([]);
    }
  };

  // 이미지에서 대표색상 4개 추출 후 각각 mood 매핑
  const handleImageLoad = async () => {
    if (!imgRef.current) return;
    const colorThief = new ColorThief();
    try {
      const palette: [number, number, number][] = await colorThief.getPalette(imgRef.current, 5);
      const colorMoodArr = palette.slice(0, 4).map(rgb => {
        const color = rgbToSimpleColor(rgb);
        // 여러 무드 중 랜덤 1개
        const moods = colorToMood[color] || ["감각적인"];
        const mood = moods[Math.floor(Math.random() * moods.length)];
        return { color, mood };
      });
      setColorMoods(colorMoodArr);
    } catch (e) {
      setColorMoods([{ color: "gray", mood: "감각적인" }]);
    }
  };

  // 대표색상별 무드에서 2개씩 짝지어 2줄 문장 4개 생성
  const generate = async () => {
    if (!colorMoods.length) return;
    setLoading(true);
    setTimeout(() => {
      // 대표색상별 무드에서 2개씩 짝지어 2줄 문장 4개 생성
      let phrases: string[] = [];
      for (let i = 0; i < 4; i++) {
        const idx1 = Math.floor(Math.random() * colorMoods.length);
        let idx2 = Math.floor(Math.random() * colorMoods.length);
        while (idx2 === idx1 && colorMoods.length > 1) {
          idx2 = Math.floor(Math.random() * colorMoods.length);
        }
        const mood1 = colorMoods[idx1].mood;
        const mood2 = colorMoods[idx2].mood;
        const phrase = generateConnectedPhrase(mood1, mood2);
        if (!phrases.includes(phrase)) phrases.push(phrase);
      }
      setResult(phrases);
      setLoading(false);
    }, 600);
  };

  return (
    <div style={{ padding: 24, maxWidth: 480, margin: "32px auto" }}>
      <h1 style={{ fontSize: 22, fontWeight: 700, marginBottom: 16 }}>배너 문구 생성기 (무료버전)</h1>
      <input type="file" accept="image/*" onChange={handleUpload} />

      {previewUrl && (
        <img
          ref={imgRef}
          src={previewUrl}
          alt="preview"
          crossOrigin="anonymous"
          onLoad={handleImageLoad}
          style={{ borderRadius: 12, boxShadow: "0 2px 8px #e0e7ef", margin: "18px 0", maxWidth: "100%" }}
        />
      )}

      {/* 대표 색상/무드 모두 보여주기 */}
      {colorMoods.length > 0 && (
        <div style={{ marginBottom: 12, color: '#64748b', fontSize: 15 }}>
          {colorMoods.map((cm, i) => (
            <div key={i}>
              대표 색상 {i+1}: <b>{cm.color}</b> / 추출 무드: <b>{cm.mood}</b>
            </div>
          ))}
        </div>
      )}

      <div style={{ display: "flex", gap: 16, alignItems: "center", margin: "16px 0" }}>
        <label>
          <input
            type="radio"
            checked={copyType === "mypage"}
            onChange={() => setCopyType("mypage")}
          />
          마이페이지 배너 (13자×2줄)
        </label>
        <label>
          <input
            type="radio"
            checked={copyType === "ribbon"}
            onChange={() => setCopyType("ribbon")}
          />
          띠배너 (18자 1줄)
        </label>
      </div>

      <button
        onClick={generate}
        disabled={loading || !image || !colorMoods.length}
        style={{
          background: "#3b82f6",
          color: "white",
          fontWeight: 600,
          borderRadius: 8,
          padding: "10px 28px",
          fontSize: 16,
          border: "none",
          cursor: loading || !image || !colorMoods.length ? "not-allowed" : "pointer",
          marginBottom: 18,
        }}
      >
        {loading ? "문구 생성 중..." : "문구 생성하기"}
      </button>

      {result.length > 0 && (
        <div style={{ background: "#f8fafc", borderRadius: 10, padding: 18, marginTop: 10 }}>
          {result.map((line, i) => (
            <div key={i} style={{ whiteSpace: "pre-line", fontSize: 15, marginBottom: 8 }}>{line}</div>
          ))}
        </div>
      )}
    </div>
  );
};

export default BannerCopyGenerator;
